changeSet.sql:
-- ================================================================= -- 0) TEMIZLIK — bagimlilik sirasina gore (menu -> grant -> yetki) -- ================================================================= delete from s_menu; delete from s_role_permission; delete from s_permission;
-- ================================================================= -- 1) YETKILER -- name : benzersiz teknik ad (controller adi veya menu grubu) -- title : kullaniciya gorunen aciklama -- ================================================================= insert into s_permission (id, name, title, created_date) values (nextval('SEQ_S_PERMISSION'), 'DashboardView', 'Dashboard', now()), (nextval('SEQ_S_PERMISSION'), 'CalismaAlaniMenu', 'Çalışma Alanı', now()), (nextval('SEQ_S_PERMISSION'), 'ProjectController', 'Projeler', now()), (nextval('SEQ_S_PERMISSION'), 'TaskController', 'Görevler', now()), (nextval('SEQ_S_PERMISSION'), 'SprintController', 'Sprintler', now()), (nextval('SEQ_S_PERMISSION'), 'SistemAyarlariMenu', 'Sistem Ayarları', now()), (nextval('SEQ_S_PERMISSION'), 'UserController', 'Kullanıcılar', now()), (nextval('SEQ_S_PERMISSION'), 'RolAtamaController', 'Kullanıcılara Rol Atama', now()), (nextval('SEQ_S_PERMISSION'), 'PartnerController', 'Partnerler', now());
-- ================================================================= -- 2) ROL -> YETKI MATRISI -- =================================================================
-- ADMIN: tum yetkiler (yeni yetki eklendiginde otomatik kapsanir) insert into s_role_permission (role_id, permission_id) select r.id, p.id from s_role r cross join s_permission p where r.name = 'ADMIN';
-- CUSTOMER_ADMIN: Calisma Alani + kullanici/rol yonetimi -- (Partner ekranini GORMEZ; partner yonetimi sistem yoneticisindedir) insert into s_role_permission (role_id, permission_id) select r.id, p.id from s_role r cross join s_permission p where r.name = 'CUSTOMER_ADMIN' and p.name in ('DashboardView', 'CalismaAlaniMenu', 'ProjectController', 'TaskController', 'SprintController', 'SistemAyarlariMenu', 'UserController', 'RolAtamaController');
-- CUSTOMER: yalnizca Calisma Alani ekranlari insert into s_role_permission (role_id, permission_id) select r.id, p.id from s_role r cross join s_permission p where r.name = 'CUSTOMER' and p.name in ('DashboardView', 'CalismaAlaniMenu', 'ProjectController', 'TaskController', 'SprintController');
-- ================================================================= -- 3) MENULER -- Once kok menuler, sonra alt menuler (parent_id baslikla bulunur) -- =================================================================
-- --- Kok menuler --- insert into s_menu (id, parent_id, title, page, icon, menu_order, active, permission_id, created_date) values (nextval('SEQ_S_MENU'), null, 'Dashboard', '/dashboard', 'dashboard', 1, true, (select id from s_permission where name = 'DashboardView'), now()), (nextval('SEQ_S_MENU'), null, 'Çalışma Alanı', null, 'workspaces', 10, true, (select id from s_permission where name = 'CalismaAlaniMenu'), now()), (nextval('SEQ_S_MENU'), null, 'Sistem Ayarları', null, 'settings', 20, true, (select id from s_permission where name = 'SistemAyarlariMenu'), now());
-- --- Calisma Alani alti --- insert into s_menu (id, parent_id, title, page, icon, menu_order, active, permission_id, created_date) values (nextval('SEQ_S_MENU'), (select id from s_menu where title = 'Çalışma Alanı' and parent_id is null), 'Projeler', '/projeler', 'folder', 1, true, (select id from s_permission where name = 'ProjectController'), now()), (nextval('SEQ_S_MENU'), (select id from s_menu where title = 'Çalışma Alanı' and parent_id is null), 'Görevler', '/gorevler', 'task_alt', 2, true, (select id from s_permission where name = 'TaskController'), now()), (nextval('SEQ_S_MENU'), (select id from s_menu where title = 'Çalışma Alanı' and parent_id is null), 'Sprintler', '/sprintler', 'view_kanban', 3, true, (select id from s_permission where name = 'SprintController'), now());
-- --- Sistem Ayarlari alti --- insert into s_menu (id, parent_id, title, page, icon, menu_order, active, permission_id, created_date) values (nextval('SEQ_S_MENU'), (select id from s_menu where title = 'Sistem Ayarları' and parent_id is null), 'Kullanıcılar', '/sistem/kullanicilar', 'group', 1, true, (select id from s_permission where name = 'UserController'), now()), (nextval('SEQ_S_MENU'), (select id from s_menu where title = 'Sistem Ayarları' and parent_id is null), 'Kullanıcılara Rol Atama', '/sistem/rol-atama', 'manage_accounts', 2, true, (select id from s_permission where name = 'RolAtamaController'), now()), (nextval('SEQ_S_MENU'), (select id from s_menu where title = 'Sistem Ayarları' and parent_id is null), 'Partnerler', '/partnerler', 'apartment', 3, true, (select id from s_permission where name = 'PartnerController'), now());
